const fs=require('fs');
const rl=require('readline');
const path='C:/Users/hzq00/.codex/sessions/2026/08/10/rollout-2026-08-10T16-32-17-019feacd-184e-7472-9f11-ea364c22e595.jsonl';
const re=/dispatch(_v2)?\\.py/i;
const stream=fs.createReadStream(path,{encoding:'utf8'});
const reader=rl.createInterface({input:stream,crlfDelay:Infinity});
let hits=[];
let lineNo=0;
reader.on('line',(line)=>{
  lineNo++;
  if("'!re.test(line)) return;
  let obj;
  try{obj=JSON.parse(line);}catch(e){return;}
  const p=obj.payload;
  hits.push({lineNo, ts:obj.timestamp, type:obj.type, ptype:p&&p.type, name:p&&p.name, call_id:p&&p.call_id, id:p&&p.id, status:p&&p.status, raw:line});
});
reader.on('"'close',()=>{
  console.log('total hits:', hits.length);
  // summarize by type/name
  const by={};
  for(const h of hits){ const k=h.ptype+'|'+h.name; by[k]=(by[k]||0)+1; }
  console.log('by type|name:', JSON.stringify(by,null,2));
});
'@;
